from pathlib import Path
import shutil
from datetime import datetime

ROOT = Path(__file__).resolve().parent
BACKUP = ROOT / "_backup_sprint2" / datetime.now().strftime("%Y%m%d_%H%M%S")

FILES = {
    "backend/parser/site_parser.py": 'from __future__ import annotations\n\nimport json\nimport re\nfrom collections import deque\nfrom datetime import datetime\nfrom urllib.parse import urljoin, urlparse, urlunparse\n\nimport requests\nfrom bs4 import BeautifulSoup\n\nfrom backend.config import BASE_DIR\n\nHEADERS = {"User-Agent": "LotusAIManager/0.9"}\nPAGE_TYPES_FILE = BASE_DIR / "backend" / "config" / "page_types.json"\nSKIP_EXTENSIONS = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".ico", ".pdf", ".zip", ".rar", ".css", ".js", ".xml", ".mp4", ".webm")\nBAD_TEXT_PARTS = ("li_ph", "li_req", "li_nm", "recaptcha", "window.", "function(", "document.", "jquery", "prototype")\nTPRODUCT_PATTERN = re.compile(r"(?:https?://[^\\s\\"\'<>]+/tproduct/[^\\s\\"\'<>\\\\]+|/[^\\s\\"\'<>]*/tproduct/[^\\s\\"\'<>\\\\]+)", re.IGNORECASE)\nPRODUCT_CATALOG_WORDS = ("благовони", "серьги", "статуи", "статуя", "чётки", "четки", "подвески", "гау", "ваджра", "колокольчик", "болс", "сувенир", "купить", "доставка по россии", "доставка по рф")\n\ndef normalize_url(url: str) -> str:\n    parsed = urlparse(url)\n    cleaned = parsed._replace(query="", fragment="")\n    value = urlunparse(cleaned).rstrip("/")\n    return value or f"{parsed.scheme}://{parsed.netloc}"\n\ndef is_same_domain(url: str, base_url: str) -> bool:\n    return urlparse(url).netloc == urlparse(base_url).netloc\n\ndef is_crawlable(url: str, base_url: str) -> bool:\n    return is_same_domain(url, base_url) and not urlparse(url).path.lower().endswith(SKIP_EXTENSIONS)\n\ndef load_manual_page_types() -> dict:\n    if not PAGE_TYPES_FILE.exists():\n        return {}\n    try:\n        data = json.loads(PAGE_TYPES_FILE.read_text(encoding="utf-8"))\n        return {normalize_url(url): settings for url, settings in data.items()}\n    except (json.JSONDecodeError, OSError):\n        return {}\n\ndef manual_seed_urls(base_url: str) -> list[str]:\n    return [url for url in load_manual_page_types() if is_crawlable(url, base_url)]\n\ndef clean_text(text: str) -> str:\n    lines, seen = [], set()\n    for raw in text.splitlines():\n        line = re.sub(r"\\s{2,}", " ", raw.strip())\n        if len(line) < 3 or any(bad in line.lower() for bad in BAD_TEXT_PARTS):\n            continue\n        if line.count("{") + line.count("}") + line.count("[") + line.count("]") > 2:\n            continue\n        if re.search(r"\\\\u[0-9a-fA-F]{4}", line):\n            continue\n        key = line.lower()\n        if key in seen and len(line) < 100:\n            continue\n        seen.add(key)\n        lines.append(line)\n    return re.sub(r"\\n{3,}", "\\n\\n", "\\n".join(lines)).strip()\n\ndef classify_page(url: str, title: str, text: str) -> dict:\n    normalized_url = normalize_url(url)\n    manual = load_manual_page_types().get(normalized_url)\n    if manual:\n        return {"page_type": manual.get("type", "general"), "display_title": manual.get("title") or title, "enabled": bool(manual.get("enabled", True)), "priority": int(manual.get("priority", 0)), "classification_source": "manual"}\n\n    path = urlparse(normalized_url).path.lower().rstrip("/")\n    hay = f"{title}\\n{text}".lower()\n\n    if "/tproduct/" in path:\n        page_type = "product"\n    elif path == "/svet-lotosa-shop":\n        page_type = "shop_catalog"\n    elif path == "/buddolog-consult":\n        page_type = "psychologist"\n    elif path == "/reviews":\n        page_type = "reviews"\n    elif path == "/privacy":\n        page_type = "legal"\n    elif path == "/putretrit":\n        page_type = "tour_catalog"\n    elif "контактная информация" in hay or "связаться с нами" in hay:\n        page_type = "contacts"\n    elif any(word in hay for word in PRODUCT_CATALOG_WORDS):\n        page_type = "product_catalog"\n    elif path in ("", "/"):\n        page_type = "general"\n    else:\n        tour_signals = ("план маршрута", "день 1", "забронировать тур", "бронирование тура", "в стоимость входит")\n        tour_signal_count = sum(signal in hay for signal in tour_signals)\n        url_tour_signal = any(marker in path for marker in ("-tur-", "tour-", "-tour", "kailas", "kailash", "lapchi", "tibet", "butan", "bhutan", "ladakh", "altai", "beluha", "markha", "kullu"))\n        page_type = "tour" if tour_signal_count >= 2 or (url_tour_signal and tour_signal_count >= 1) else "general"\n\n    priorities = {"tour": 100, "product": 100, "psychologist": 100, "tour_catalog": 80, "shop_catalog": 80, "product_catalog": 70, "reviews": 50, "contacts": 40, "legal": 0, "general": 10}\n    return {"page_type": page_type, "display_title": title, "enabled": True, "priority": priorities.get(page_type, 0), "classification_source": "automatic"}\n\ndef fetch_response(url: str) -> requests.Response:\n    response = requests.get(url, headers=HEADERS, timeout=30)\n    response.raise_for_status()\n    return response\n\ndef extract_page(url: str) -> dict:\n    response = fetch_response(url)\n    soup = BeautifulSoup(response.text, "lxml")\n    for tag in soup(["script", "style", "noscript", "svg", "iframe"]):\n        tag.decompose()\n    for tag in soup.select(\'[aria-hidden="true"], [style*="display:none"], [style*="display: none"]\'):\n        tag.decompose()\n    original_title = soup.title.get_text(strip=True) if soup.title else url\n    text = clean_text(soup.get_text("\\n", strip=True))\n    classification = classify_page(url, original_title, text)\n    return {"url": normalize_url(url), "title": classification["display_title"], "original_title": original_title, "text": text, "chars": len(text), "page_type": classification["page_type"], "enabled": classification["enabled"], "priority": classification["priority"], "classification_source": classification["classification_source"]}\n\ndef extract_tproduct_links(html: str, current_url: str, base_url: str) -> set[str]:\n    links = set()\n    for match in TPRODUCT_PATTERN.findall(html):\n        candidate = match.replace("\\\\/", "/").rstrip("\\\\,;)")\n        full_url = normalize_url(urljoin(current_url + "/", candidate))\n        if is_crawlable(full_url, base_url):\n            links.add(full_url)\n    return links\n\ndef extract_links(url: str, base_url: str) -> list[str]:\n    response = fetch_response(url)\n    soup = BeautifulSoup(response.text, "lxml")\n    links = set()\n    for anchor in soup.find_all("a", href=True):\n        href = anchor["href"].strip()\n        if not href or href.startswith(("mailto:", "tel:", "javascript:", "whatsapp:", "tg:", "#")):\n            continue\n        full_url = normalize_url(urljoin(url + "/", href))\n        if is_crawlable(full_url, base_url):\n            links.add(full_url)\n    links.update(extract_tproduct_links(response.text, url, base_url))\n    return sorted(links)\n\ndef discover_links(base_url: str, limit: int = 300, max_depth: int = 3) -> list[str]:\n    base_url = normalize_url(base_url)\n    queue = deque([(base_url, 0)])\n    for seed_url in manual_seed_urls(base_url):\n        if seed_url != base_url:\n            queue.append((seed_url, 0))\n    visited, discovered = set(), []\n    while queue and len(discovered) < limit:\n        current_url, depth = queue.popleft()\n        if current_url in visited:\n            continue\n        visited.add(current_url)\n        discovered.append(current_url)\n        if depth >= max_depth:\n            continue\n        try:\n            child_links = extract_links(current_url, base_url)\n        except requests.RequestException:\n            continue\n        for child_url in child_links:\n            if child_url not in visited:\n                queue.append((child_url, depth + 1))\n    return discovered\n\ndef chunk_text(text: str, chunk_size: int = 1100, overlap: int = 150) -> list[str]:\n    paragraphs = [part.strip() for part in text.split("\\n") if part.strip()]\n    chunks, current = [], ""\n    for paragraph in paragraphs:\n        candidate = f"{current}\\n{paragraph}".strip()\n        if len(candidate) <= chunk_size:\n            current = candidate\n            continue\n        if len(current) > 100:\n            chunks.append(current)\n        current = paragraph\n    if len(current) > 100:\n        chunks.append(current)\n\n    final_chunks = []\n    for chunk in chunks:\n        if len(chunk) <= chunk_size + 200:\n            final_chunks.append(chunk)\n            continue\n        start = 0\n        while start < len(chunk):\n            part = chunk[start:start + chunk_size].strip()\n            if len(part) > 100:\n                final_chunks.append(part)\n            start += chunk_size - overlap\n    return final_chunks\n\ndef parse_site(base_url: str, limit: int = 300, max_depth: int = 3) -> dict:\n    pages, chunks, errors = [], [], []\n    for url in discover_links(base_url, limit=limit, max_depth=max_depth):\n        try:\n            page = extract_page(url)\n            if page["chars"] <= 100 or not page["enabled"]:\n                continue\n            page_chunks = chunk_text(page["text"])\n            page["chunks_count"] = len(page_chunks)\n            pages.append(page)\n            for index, chunk in enumerate(page_chunks):\n                chunks.append({"id": str(len(chunks) + 1), "page_url": page["url"], "page_title": page["title"], "page_type": page["page_type"], "chunk_index": index, "text": chunk})\n        except Exception as exc:\n            errors.append({"url": url, "error": str(exc)})\n    type_counts = {}\n    for page in pages:\n        type_counts[page["page_type"]] = type_counts.get(page["page_type"], 0) + 1\n    return {"site": base_url, "updated_at": datetime.now().isoformat(timespec="seconds"), "pages_count": len(pages), "chunks_count": len(chunks), "type_counts": type_counts, "errors_count": len(errors), "pages": pages, "chunks": chunks, "errors": errors}\n',
    "backend/rag/retriever.py": 'from __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\n\nfrom backend.storage.database import get_connection, initialize_database\n\nSTOPWORDS = {"что", "как", "где", "когда", "есть", "мне", "можно", "хочу", "покажи", "расскажи", "про", "для", "или", "это", "какой", "какая"}\nINTENT_TYPES = {\n    "tour": {"тур", "поездка", "путешествие", "кайлас", "лапчи", "тибет", "непал", "бутан", "индия", "ретрит"},\n    "product": {"товар", "купить", "статуя", "чётки", "четки", "серьги", "благовония", "гау", "подвеска"},\n    "psychologist": {"психолог", "консультация", "стресс", "эмоции", "буддолог"},\n}\n\n@dataclass\nclass SearchResult:\n    document_id: str\n    title: str\n    url: str\n    page_type: str\n    content: str\n    score: float\n\ndef tokenize(text: str) -> list[str]:\n    words = re.findall(r"[a-zA-Zа-яА-ЯёЁ0-9]{3,}", text.lower())\n    return [word for word in words if word not in STOPWORDS]\n\ndef detect_intent(query: str) -> str | None:\n    words = set(tokenize(query))\n    best_type, best_score = None, 0\n    for page_type, markers in INTENT_TYPES.items():\n        score = len(words & markers)\n        if score > best_score:\n            best_type, best_score = page_type, score\n    return best_type\n\ndef search(query: str, limit: int = 5) -> list[SearchResult]:\n    initialize_database()\n    tokens = tokenize(query)\n    intent = detect_intent(query)\n    with get_connection() as connection:\n        rows = connection.execute("""\n            SELECT d.id AS document_id, d.title, d.url, d.page_type, d.priority, c.content\n            FROM document_chunks c\n            JOIN documents d ON d.id = c.document_id\n            WHERE d.enabled = 1\n        """).fetchall()\n\n    results = []\n    for row in rows:\n        title_lower = row["title"].lower()\n        text = f"{row[\'title\']} {row[\'content\']}".lower()\n        score = float(row["priority"]) / 20.0\n        for token in tokens:\n            if token in title_lower:\n                score += 8\n            if token in text:\n                score += 3 + text.count(token)\n        if intent:\n            if row["page_type"] == intent:\n                score += 20\n            elif intent == "product" and row["page_type"] in {"product_catalog", "shop_catalog"}:\n                score += 8\n            elif intent == "tour" and row["page_type"] == "tour_catalog":\n                score += 8\n            else:\n                score -= 12\n        if score > 0:\n            results.append(SearchResult(row["document_id"], row["title"], row["url"], row["page_type"], row["content"], score))\n\n    results.sort(key=lambda item: item.score, reverse=True)\n    unique, seen_urls = [], set()\n    for result in results:\n        if result.url in seen_urls:\n            continue\n        seen_urls.add(result.url)\n        unique.append(result)\n        if len(unique) >= limit:\n            break\n    return unique\n\ndef print_results(query: str) -> None:\n    results = search(query)\n    print(f"Query: {query}")\n    print(f"Intent: {detect_intent(query) or \'general\'}")\n    print()\n    if not results:\n        print("Nothing found")\n        return\n    for index, result in enumerate(results, start=1):\n        print(f"{index}. [{result.page_type}] {result.title}")\n        print(f"   score: {result.score:.1f}")\n        print(f"   {result.url}")\n\nif __name__ == "__main__":\n    import sys\n    query = " ".join(sys.argv[1:]).strip() or "Есть тур в Индию?"\n    print_results(query)\n',
    "test_search.bat": '@echo off\nchcp 65001 > nul\ncall .venv\\Scripts\\activate.bat\necho ==========================================\necho TOUR SEARCH\necho ==========================================\npython -m backend.rag.retriever "Есть тур в Индию?"\necho.\necho ==========================================\necho PRODUCT SEARCH\necho ==========================================\npython -m backend.rag.retriever "Хочу купить статую"\necho.\necho ==========================================\necho PSYCHOLOGIST SEARCH\necho ==========================================\npython -m backend.rag.retriever "Есть консультация психолога?"\necho.\npause\n',
}

for relative, content in FILES.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        backup_target = BACKUP / relative
        backup_target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, backup_target)
    target.write_text(content, encoding="utf-8")

print("Sprint 2 installed.")
print("Backup:", BACKUP)
print("Next:")
print("1. run.bat")
print("2. Open /admin and update site")
print("3. Stop server")
print("4. python -m backend.rag.knowledge_builder")
print("5. test_search.bat")
